import SortIcon from 'assets/icons/sort-descending-3.svg';
import type { ButtonProps, ButtonSize } from 'components/UI';

import { StyledButton, StyledRoundButton } from './ExpandButtonWithImg.styles';

const iconSize: Record<ButtonSize, string> = {
  small: '16px',
  medium: '24px',
  large: '32px',
};

export type ExpandButtonShape = 'default' | 'round';

interface ExpandBtnProps extends Omit<ButtonProps, 'value' | 'size'> {
  value: boolean;
  onValueChange: (value: boolean) => void;
  disabled?: ButtonProps['disabled'];
  size?: ButtonProps['size'];
  shape?: ExpandButtonShape;
  dataTestId?: string;
}

export const ExpandButtonWithImg = ({
  value,
  onValueChange,
  size = 'medium',
  shape = 'default',
  disabled,
  dataTestId,
}: ExpandBtnProps) => {
  const commonProps = {
    onClick: () => onValueChange(!value),
    disabled,
    variant: 'secondary' as const,
    size,
    'data-testid': dataTestId ? `button-${dataTestId}` : undefined,
    children: (
      <img src={SortIcon} alt="sort" style={{ width: iconSize[size] }} />
    ),
  };

  if (shape === 'round') {
    return <StyledRoundButton {...commonProps} $isExpanded={value} />;
  }

  return (
    <StyledButton {...commonProps} $isExpanded={value} $disabled={disabled} />
  );
};
